import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageCircle, X, Send, Users, User, ChevronLeft, Shield } from 'lucide-react';
import { cn } from '../lib/utils';

// Types for our chat system
type Message = {
    id: string;
    sender: string;
    text: string;
    timestamp: Date;
    isAdminLog?: boolean;
};

type Chat = {
    id: string;
    name: string;
    type: 'group' | 'direct';
    unread?: number;
    online?: boolean;
};

// Mock Data
const MOCK_CHATS: Chat[] = [
    { id: 'g1', name: 'Emergency Team', type: 'group', unread: 2, online: true },
    { id: 'g2', name: 'General Staff', type: 'group', online: false },
    { id: 'u1', name: ' Dr. Sandeep Kumar Shah', type: 'direct', unread: 1, online: true },
    { id: 'u2', name: 'Reception Desk', type: 'direct', online: true },
    { id: 'g3', name: 'Patient Support', type: 'group', online: false },
];

const INITIAL_MESSAGES: Record<string, Message[]> = {
    'g1': [
        { id: '1', sender: 'Dr. Priya', text: 'Patient incoming in 5 mins.', timestamp: new Date(Date.now() - 1000 * 60 * 5) },
        { id: '2', sender: 'Nurse John', text: 'OT 2 is ready.', timestamp: new Date(Date.now() - 1000 * 60 * 2) },
    ],
    'u1': [
        { id: '1', sender: 'Dr. Sandeep Sharma', text: 'Please send the patient report.', timestamp: new Date(Date.now() - 1000 * 60 * 60) },
    ],
    'g3': [
        { id: '1', sender: 'System', text: 'Welcome to Patient Support. How can we help you?', timestamp: new Date(Date.now() - 1000 * 60 * 60 * 24) },
    ]
};

interface ChatWidgetProps {
    isOpen: boolean;
    onClose: () => void;
}

const ChatWidget = ({ isOpen, onClose }: ChatWidgetProps) => {
    const [activeChatId, setActiveChatId] = useState<string | null>(null);
    const [messages, setMessages] = useState<Record<string, Message[]>>(INITIAL_MESSAGES);
    const [inputText, setInputText] = useState('');
    const [isAdminMode, setIsAdminMode] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const activeChat = MOCK_CHATS.find(c => c.id === activeChatId);
    const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];

    // Auto-scroll to bottom of chat
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [currentMessages, activeChatId, isOpen]);

    const handleSend = () => {
        if (!inputText.trim() || !activeChatId) return;

        // 1. Add User Message
        const newMessage: Message = {
            id: Date.now().toString(),
            sender: isAdminMode ? 'Admin' : 'You',
            text: inputText,
            timestamp: new Date(),
        };

        setMessages(prev => ({
            ...prev,
            [activeChatId]: [...(prev[activeChatId] || []), newMessage]
        }));
        setInputText('');

        // 2. Simulate WebSocket/Firebase Response
        setTimeout(() => {
            const reply: Message = {
                id: (Date.now() + 1).toString(),
                sender: activeChat?.type === 'group' ? 'System' : activeChat?.name || 'User',
                text: 'Message received. (This is a simulated response)',
                timestamp: new Date(),
            };
            setMessages(prev => ({
                ...prev,
                [activeChatId]: [...(prev[activeChatId] || []), reply]
            }));
        }, 1000);
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0, y: 20, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 20, scale: 0.95 }}
                    className="fixed bottom-4 right-4 w-full max-w-md h-[600px] bg-white rounded-2xl shadow-2xl border border-gray-200 z-[100] flex flex-col overflow-hidden font-sans"
                >
                    {/* Header */}
                    <div className="bg-blue-900 text-white p-4 flex justify-between items-center shrink-0">
                        <div className="flex items-center gap-2">
                            <MessageCircle className="w-5 h-5" />
                            <div>
                                <h3 className="font-bold text-sm leading-tight">Internal Communication</h3>
                                <p className="text-[10px] text-blue-200">Secure Hospital Network</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setIsAdminMode(!isAdminMode)}
                                className={cn("text-[10px] px-2 py-1 rounded border border-white/20 hover:bg-white/10 flex items-center gap-1 transition-colors", isAdminMode && "bg-red-600 border-red-600")}
                                title="Toggle Admin Monitoring"
                            >
                                <Shield className="w-3 h-3" /> {isAdminMode ? 'ADMIN' : 'USER'}
                            </button>
                            <button onClick={onClose} className="hover:bg-white/20 p-1 rounded transition-colors">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    <div className="flex-1 flex overflow-hidden relative">
                        {/* Sidebar / Chat List */}
                        <div className={cn(
                            "absolute inset-0 z-10 bg-gray-50 flex flex-col transition-transform duration-300 md:relative md:w-1/3 md:border-r md:border-gray-200",
                            activeChatId ? "-translate-x-full md:translate-x-0" : "translate-x-0"
                        )}>
                            <div className="p-3 border-b border-gray-200 bg-white">
                                <input placeholder="Search chats..." className="w-full px-3 py-2 rounded-lg border border-gray-200 text-xs bg-gray-50 focus:outline-none focus:border-blue-900" />
                            </div>
                            <div className="flex-1 overflow-y-auto">
                                {MOCK_CHATS.map(chat => (
                                    <div key={chat.id} onClick={() => setActiveChatId(chat.id)} className={cn("p-3 cursor-pointer hover:bg-white transition-colors border-b border-gray-100 group", activeChatId === chat.id && "bg-white border-l-4 border-l-blue-900")}>
                                        <div className="flex justify-between items-center mb-1">
                                            <div className="flex items-center gap-2">
                                                <h4 className="font-bold text-xs text-gray-800 group-hover:text-blue-900">{chat.name}</h4>
                                                {chat.online && <div className="w-2 h-2 rounded-full bg-green-500" title="Online"></div>}
                                            </div>
                                            {chat.unread && <span className="bg-red-500 text-white text-[9px] px-1.5 py-0.5 rounded-full font-bold">{chat.unread}</span>}
                                        </div>
                                        <p className="text-[10px] text-gray-500 flex items-center gap-1 uppercase tracking-wider font-semibold">
                                            {chat.type === 'group' ? <Users className="w-3 h-3" /> : <User className="w-3 h-3" />} {chat.type}
                                        </p>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Chat Area */}
                        <div className={cn("absolute inset-0 z-20 bg-white flex flex-col transition-transform duration-300 md:relative md:w-2/3", activeChatId ? "translate-x-0" : "translate-x-full md:translate-x-0")}>
                            {activeChatId ? (
                                <>
                                    <div className="p-3 border-b border-gray-100 flex items-center gap-2 shadow-sm bg-white shrink-0">
                                        <button onClick={() => setActiveChatId(null)} className="md:hidden p-1 hover:bg-gray-100 rounded text-gray-500"><ChevronLeft className="w-5 h-5" /></button>
                                        <div className="flex items-center gap-2">
                                            <span className="font-bold text-sm text-gray-800 truncate">{activeChat?.name}</span>
                                            {activeChat?.online && <div className="w-2.5 h-2.5 rounded-full bg-green-500" title="Online"></div>}
                                        </div>
                                        {isAdminMode && <span className="ml-auto text-[9px] text-red-600 font-black border border-red-100 px-2 py-0.5 rounded bg-red-50 uppercase tracking-wider">Monitoring</span>}
                                    </div>
                                    <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50">
                                        {currentMessages.map(msg => (
                                            <div key={msg.id} className={cn("flex flex-col max-w-[85%]", msg.sender === 'You' || msg.sender === 'Admin' ? "self-end items-end" : "self-start items-start")}>
                                                <div className={cn("px-4 py-2 rounded-2xl text-xs leading-relaxed shadow-sm", (msg.sender === 'You' || msg.sender === 'Admin') ? "bg-blue-900 text-white rounded-br-none" : "bg-white border border-gray-200 text-gray-700 rounded-bl-none")}>
                                                    {activeChat?.type === 'group' && msg.sender !== 'You' && msg.sender !== 'Admin' && <p className="text-[9px] font-bold text-blue-900/70 mb-0.5 uppercase tracking-wider">{msg.sender}</p>}
                                                    {msg.text}
                                                </div>
                                                <span className="text-[9px] text-gray-400 mt-1 px-1">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                            </div>
                                        ))}
                                        <div ref={messagesEndRef} />
                                    </div>
                                    <div className="p-3 border-t border-gray-100 bg-white shrink-0">
                                        <form onSubmit={(e) => { e.preventDefault(); handleSend(); }} className="flex gap-2">
                                            <input value={inputText} onChange={(e) => setInputText(e.target.value)} placeholder="Type a message..." className="flex-1 px-4 py-2.5 bg-gray-100 rounded-full text-xs focus:outline-none focus:ring-2 focus:ring-blue-900/20 transition-all" />
                                            <button type="submit" className="p-2.5 bg-blue-900 text-white rounded-full hover:bg-blue-800 transition-colors shadow-md"><Send className="w-4 h-4" /></button>
                                        </form>
                                    </div>
                                </>
                            ) : (
                                <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-8 text-center bg-slate-50/50"><MessageCircle className="w-16 h-16 mb-3 opacity-20" /><p className="text-sm font-medium">Select a conversation to start chatting</p></div>
                            )}
                        </div>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

export default ChatWidget;

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate, useLocation } from 'react-router-dom';
import { Calendar, Phone, Mail, Clock, User, CheckCircle, Plus, X, ArrowRight, ArrowLeft, Stethoscope, MapPin, Globe } from 'lucide-react';
import Button from './Button';
import { postData } from '../lib/api';

const DOCTORS_DATA = [
    { name: 'Dr. Sandeep Sharma', specialty: 'Cardiology', image: 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?auto=format&fit=crop&q=80&w=1000' },
    { name: 'Dr. Priya Adhikari', specialty: 'Gynecology', image: 'https://images.unsplash.com/photo-1594824476967-48c8b964273f?auto=format&fit=crop&q=80&w=1000' },
    { name: 'Dr. Rajesh Gupta', specialty: 'Neurology', image: 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?auto=format&fit=crop&q=80&w=1000' },
    { name: 'Dr. Sarah Johnson', specialty: 'Cardiology', image: 'https://images.unsplash.com/photo-1614608682850-e0d6ed316d47?auto=format&fit=crop&q=80&w=1000' },
    { name: 'Dr. Michael Chen', specialty: 'Neurology', image: 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&q=80&w=1528' },
    { name: 'Dr. Emily Williams', specialty: 'Pediatrics', image: 'https://images.unsplash.com/photo-1594824476967-48c8b964273f?auto=format&fit=crop&q=80&w=1374' },
    { name: 'Dr. Robert Brown', specialty: 'Orthopedics', image: 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?auto=format&fit=crop&q=80&w=1470' },
];

const DoctorAppointment = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        age: '',
        gender: 'Select Gender',
        contactNumber: '',
        email: '',
        department: 'Cardiology',
        doctor: 'Any Available Doctor',
        shift: 'Morning',
        address: '',
        nationality: 'Nepali',
        province: 'Province No. 2 (Madhesh)',
        district: '',
        message: ''
    });
    const [isSubmitted, setIsSubmitted] = useState(false);
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [appointmentDates, setAppointmentDates] = useState<string[]>([]);
    const [currentDate, setCurrentDate] = useState('');
    const [step, setStep] = useState(1);
    const navigate = useNavigate();
    const location = useLocation();

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    useEffect(() => {
        window.scrollTo(0, 0);
    }, []);

    useEffect(() => {
        if (location.state) {
            const { doctorName, department } = location.state;
            setFormData(prev => ({
                ...prev,
                doctor: doctorName || prev.doctor,
                department: department || prev.department
            }));
        }
    }, [location.state]);

    const validateForm = () => {
        const newErrors: Record<string, string> = {};

        if (!formData.fullName.trim()) newErrors.fullName = "Patient name is required.";
        if (!formData.age) {
            newErrors.age = "Age is required.";
        } else if (isNaN(Number(formData.age)) || Number(formData.age) <= 0) {
            newErrors.age = "Please enter a valid age.";
        }
        if (formData.gender === 'Select Gender') newErrors.gender = "Please select a gender.";
        if (!formData.contactNumber.trim()) {
            newErrors.contactNumber = "Phone number is required.";
        } else if (!/^\+?[0-9\s-]{7,}$/.test(formData.contactNumber)) {
            newErrors.contactNumber = "Please enter a valid phone number.";
        }
        if (!formData.nationality.trim()) newErrors.nationality = "Nationality is required.";
        if (formData.province === 'Select Province') newErrors.province = "Please select a province.";
        if (!formData.district.trim()) newErrors.district = "District is required.";
        if (formData.email.trim() && !/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = "Please enter a valid email address.";
        }
        if (appointmentDates.length === 0) {
            newErrors.appointmentDates = "Please select at least one appointment date.";
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateForm()) {
            return;
        }
        try {
            await postData('/appointments', { ...formData, appointmentDates });
            setIsSubmitted(true);
            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (error) {
            console.error('Appointment request failed:', error);
            alert('Failed to submit appointment request.');
        }
    };

    if (isSubmitted) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center px-4 py-20 relative overflow-hidden">
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-5"></div>
                <motion.div
                    initial={{ opacity: 0, scale: 0.9, y: 20 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    className="bg-white p-10 rounded-3xl shadow-2xl max-w-md w-full text-center relative z-10 border border-gray-100"
                >
                    <div className="w-24 h-24 bg-green-50 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                        <motion.div
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            transition={{ type: "spring", stiffness: 200, damping: 10, delay: 0.2 }}
                        >
                            <CheckCircle className="w-12 h-12 text-green-500" />
                        </motion.div>
                    </div>
                    <h2 className="text-3xl font-black text-blue-900 mb-3 tracking-tight">Request Submitted!</h2>
                    <p className="text-gray-500 mb-8 leading-relaxed">
                        Thank you, {formData.fullName}. Your appointment request has been received. Our team will contact you shortly at {formData.contactNumber} to confirm the schedule.
                    </p>
                    <Button onClick={() => navigate('/')} className="w-full bg-blue-900 text-white py-4 rounded-xl font-bold shadow-lg shadow-blue-900/20 hover:shadow-blue-900/30 transition-all hover:-translate-y-1">
                        Return to Home
                    </Button>
                </motion.div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8 relative">
            {/* Background decoration */}
            <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-b from-blue-900/5 to-transparent -z-10" />

            <div className="max-w-7xl mx-auto relative z-10">
                <div className="text-center mb-12">
                    <motion.div
                        initial={{ opacity: 0, y: -20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="inline-block mb-4 px-4 py-1.5 rounded-full bg-blue-100 text-blue-900 text-xs font-bold uppercase tracking-widest"
                    >
                        Online Booking
                    </motion.div>
                    <h1 className="text-3xl lg:text-5xl font-black text-blue-900 uppercase tracking-tight mb-6">
                        Book an <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-red-600">Appointment</span>
                    </h1>
                    <p className="text-gray-600 max-w-2xl mx-auto font-medium text-lg">
                        Schedule a consultation with our expert doctors. Simple, fast, and secure.
                    </p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    {/* Contact Info Sidebar */}
                    <div className="lg:col-span-4 space-y-6">
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            className="relative h-64 w-full rounded-3xl overflow-hidden shadow-xl group"
                        >
                            <img
                                src="https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&q=80&w=800"
                                alt="Doctor with tablet"
                                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                            />
                            <div className="absolute inset-0 bg-gradient-to-t from-blue-900/80 to-transparent flex items-end p-6">
                                <p className="text-white font-bold text-lg">World-Class Care</p>
                            </div>
                        </motion.div>
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: 0.1 }}
                            className="bg-white p-8 rounded-3xl shadow-xl border border-gray-100"
                        >
                            <h3 className="text-xl font-bold mb-6 uppercase tracking-wider">Contact Info</h3>
                            <div className="space-y-6">
                                <div className="flex items-start gap-4 group">
                                    <div className="p-3 bg-blue-50 rounded-xl text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                        <Phone className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Appointment Hotline</p>
                                        <p className="text-lg font-black text-blue-900">+977-XX-XXXXXX</p>
                                        <p className="text-sm text-gray-500 font-medium">+977-XX-XXXXXX</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4 group">
                                    <div className="p-3 bg-blue-50 rounded-xl text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                        <Mail className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Email Us</p>
                                        <p className="text-sm font-bold text-blue-900 break-all">appointment@dwarikahospital.com</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4 group">
                                    <div className="p-3 bg-blue-50 rounded-xl text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                        <Clock className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">OPD Hours</p>
                                        <p className="text-sm font-bold text-blue-900">Sunday - Friday</p>
                                        <p className="text-sm font-medium text-gray-500">8:00 AM - 5:00 PM</p>
                                    </div>
                                </div>
                            </div>
                        </motion.div>

                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: 0.2 }}
                            className="bg-red-50 p-6 rounded-3xl border border-red-100"
                        >
                            <h4 className="font-bold text-gray-800 mb-2">Need Emergency Care?</h4>
                            <p className="text-sm text-gray-600 mb-4">For immediate medical attention, please visit our Emergency Department or call our 24/7 emergency line.</p>
                            <a href="tel:+977XXXXXXXX" className="flex items-center justify-center gap-2 w-full py-3 bg-white text-red-600 font-black uppercase tracking-wider rounded-xl shadow-sm hover:shadow-md transition-all">
                                <Phone className="w-4 h-4" /> Emergency: 102
                            </a>
                        </motion.div>
                    </div>

                    {/* Appointment Form */}
                    <div className="lg:col-span-8">
                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden h-full flex flex-col"
                        >
                            {/* Stepper Header */}
                            <div className="bg-gray-50/50 px-8 py-6 border-b border-gray-100">
                                <div className="flex items-center justify-between max-w-md mx-auto">
                                    {/* Step 1 Indicator */}
                                    <div className="flex flex-col items-center gap-2 relative z-10">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold transition-all duration-300 ${step >= 1 ? 'bg-blue-900 text-white shadow-lg shadow-blue-900/20' : 'bg-gray-200 text-gray-500'}`}>
                                            {step > 1 ? <CheckCircle className="w-5 h-5" /> : "1"}
                                        </div>
                                        <span className={`text-xs font-bold uppercase tracking-wider ${step >= 1 ? 'text-blue-900' : 'text-gray-400'}`}>Doctor</span>
                                    </div>

                                    {/* Connector Line */}
                                    <div className="flex-1 h-1 bg-gray-200 mx-4 rounded-full overflow-hidden">
                                        <motion.div
                                            className="h-full bg-blue-900"
                                            initial={{ width: "0%" }}
                                            animate={{ width: step === 2 ? "100%" : "0%" }}
                                            transition={{ duration: 0.5 }}
                                        />
                                    </div>

                                    {/* Step 2 Indicator */}
                                    <div className="flex flex-col items-center gap-2 relative z-10">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold transition-all duration-300 ${step >= 2 ? 'bg-blue-900 text-white shadow-lg shadow-blue-900/20' : 'bg-gray-200 text-gray-500'}`}>2</div>
                                        <span className={`text-xs font-bold uppercase tracking-wider ${step >= 2 ? 'text-blue-900' : 'text-gray-400'}`}>Details</span>
                                    </div>
                                </div>
                            </div>

                            <div className="p-8 lg:p-10 flex-1">
                                <form onSubmit={handleSubmit} className="space-y-8">
                                    {step === 1 && (
                                        <motion.div
                                            initial={{ opacity: 0, x: -20 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            exit={{ opacity: 0, x: 20 }}
                                            className="space-y-6"
                                        >
                                            <div className="space-y-2">
                                                <h3 className="text-lg font-black text-blue-900 uppercase tracking-tight">Step 1: Select Doctor</h3>
                                                <p className="text-sm text-gray-500">Choose the department and specialist you wish to consult.</p>
                                            </div>

                                            <div className="space-y-8">
                                                <div className="space-y-2">
                                                    <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Department *</label>
                                                    <select
                                                        name="department"
                                                        value={formData.department}
                                                        onChange={(e) => setFormData(prev => ({ ...prev, department: e.target.value, doctor: 'Any Available Doctor' }))}
                                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/20 transition-all text-sm font-medium appearance-none"
