import { motion, AnimatePresence } from 'framer-motion';
import { useLocation } from 'react-router-dom';
import { useEffect, useState } from 'react';
import AboutUsSection from './AboutUsSection';
import AboutLeadership from './AboutLeadership';
import GallerySection from './Gallery';
import AboutAwards from './AboutAwards';

const tabs = [
    { id: 'overview', label: 'Overview' },
    { id: 'leadership', label: 'Leadership' },
    { id: 'awards', label: 'Awards & Accolades' },
    { id: 'gallery', label: 'Gallery' },
];

const AboutPage = () => {
    const location = useLocation();
    const initialState = location.state as { activeTab?: string } | null;
    const [activeTab, setActiveTab] = useState(initialState?.activeTab || 'overview');

    useEffect(() => {
        window.scrollTo(0, 0);
        if (initialState?.activeTab) {
            setActiveTab(initialState.activeTab);
        }
    }, [initialState]);

    return (
        <div className="min-h-screen bg-white">
            {/* Hero Section */}
            <div className="bg-blue-950 text-white py-32 px-4 relative overflow-hidden">
                <div className="absolute inset-0 z-0 opacity-20 bg-[url('https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&q=80&w=2000')] bg-cover bg-center"></div>
                <div className="max-w-4xl mx-auto relative z-10 text-center space-y-6">
                    <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="inline-block px-5 py-2 rounded-full bg-blue-900/50 text-blue-300 text-[10px] font-black uppercase tracking-[0.3em] backdrop-blur-md border border-blue-800/50">
                        About Dwarika Hospital
                    </motion.div>
                    <motion.h1 initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="text-5xl md:text-6xl lg:text-7xl font-black uppercase tracking-tight leading-tight">
                        Our Modern <br /> Healthcare Story
                    </motion.h1>
                    <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.2 }} className="text-lg md:text-xl text-blue-100/80 max-w-2xl mx-auto font-medium">
                        Leading the way in medical excellence and academic growth across Madhesh Province.
                    </motion.p>
                </div>
            </div>

            {/* Sub Navigation (Tabs) */}
            <div className="sticky top-[80px] z-40 bg-white border-b border-gray-100 shadow-sm overflow-x-auto whitespace-nowrap">
                <div className="max-w-7xl mx-auto px-6 flex justify-center">
                    {tabs.map((tab) => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`px-8 py-5 text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === tab.id ? 'text-blue-600' : 'text-gray-400 hover:text-gray-900'
                                }`}
                        >
                            {tab.label}
                            {activeTab === tab.id && (
                                <motion.div
                                    layoutId="activeTab"
                                    className="absolute bottom-0 left-0 right-0 h-1 bg-blue-600 shadow-[0_0_10px_rgb(37,99,235,0.4)]"
                                />
                            )}
                        </button>
                    ))}
                </div>
            </div>

            {/* Tab Content */}
            <div className="min-h-[600px]">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={activeTab}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        transition={{ duration: 0.4 }}
                    >
                        {activeTab === 'overview' && <AboutUsSection />}
                        {activeTab === 'leadership' && <AboutLeadership />}
                        {activeTab === 'gallery' && <GallerySection />}
                        {activeTab === 'awards' && <AboutAwards />}
                    </motion.div>
                </AnimatePresence>
            </div>
        </div>
    );
};

export default AboutPage;

