                </div>

                <div className="flex justify-center gap-2 mb-12">
                    {filters.map((item) => (
                        <button
                            key={item}
                            onClick={() => setFilter(item)}
                            className={cn(
                                "px-6 py-2 rounded-full text-sm font-bold transition-all duration-300 border-2",
