                        </div>
                        <h2 className="text-4xl md:text-6xl font-black text-slate-900 uppercase tracking-tight leading-tight">
                            News, <span className="text-blue-600">Events</span> & Media
                        </h2>
                    </div>

                    <div className="flex p-1.5 bg-slate-100/80 backdrop-blur-md rounded-2xl border border-slate-200">
                        {(['All', 'News', 'Event'] as const).map((f) => (
                            <button
                                key={f}
                                onClick={() => setFilter(f)}
                                className={`px-8 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${filter === f
                                    ? "bg-white text-blue-600 shadow-xl shadow-slate-200/50 scale-105"
                                    : "text-slate-500 hover:text-slate-800 hover:bg-white/50"
                                    }`}
                            >
                                {f}
                            </button>
                        ))}
                    </div>
                </div>

